<script lang="ts">
 import {enhance} from '$app/forms';
 let {data,form}=$props();
 let search=$state(''),showInactive=$state(false),creating=$state(false),busy=$state(false);
 const rows=$derived(data.staff.filter(s=>(showInactive||s.is_active)&&[s.name,s.kana,s.nickname,s.department].join(' ').toLowerCase().includes(search.toLowerCase())));
 function submit(){busy=true;return async({update}:{update:()=>Promise<void>})=>{try{await update();}finally{busy=false;}};}
</script>
<svelte:head><title>スタッフマスタ | Autumn Book</title></svelte:head>
<section class="staff-page">
 <header><div><p>{data.facility.name}</p><h1>スタッフマスタ</h1></div>{#if data.canEdit}<button class="primary" onclick={()=>creating=!creating}>{creating?'閉じる':'＋ スタッフを追加'}</button>{/if}</header>
 <p class="description">PMSと共通の施設別名簿です。担当者の署名には氏名を使用します。Bookで編集した氏名・表示名などは、人事名簿の再取込後も保持されます。</p>
 {#if form?.message}<p class="feedback error" role="alert">{form.message}</p>{/if}{#if form?.done}<p class="feedback" role="status">{form.done}</p>{/if}
 {#if creating&&data.canEdit}<section class="create-panel"><h2>スタッフを追加</h2><form method="POST" action="?/save" use:enhance={submit}>
 <input type="hidden" name="facilityId" value={data.facilityId}/>
 <div class="fields"><label>氏名<input name="name" required maxlength="100"/></label><label>ふりがな<input name="kana" maxlength="100"/></label><label>表示名<input name="nickname" maxlength="100"/></label><label>部署<input name="department" maxlength="100"/></label></div>
 <div class="flags"><label><input type="checkbox" name="is_active" checked/>有効</label><label><input type="checkbox" name="can_take_reservation" checked/>PMSの予約・部屋案内候補</label><label><input type="checkbox" name="exclude_from_room_assignment"/>PMSの部屋割りから除外</label></div>
 <div class="form-actions"><button class="primary" disabled={busy}>登録</button></div></form></section>{/if}
 <div class="toolbar"><input aria-label="スタッフを検索" placeholder="氏名・ふりがな・部署で検索" bind:value={search}/><label><input type="checkbox" bind:checked={showInactive}/>無効なスタッフも表示</label><span>{rows.length}名</span></div>
 <div class="roster">{#each rows as person(person.id)}<details>
 <summary><span class="avatar">{person.name.slice(0,1)}</span><span class="identity"><strong>{person.name}</strong><small>{person.kana||person.nickname||'—'}</small></span><span class="department">{person.department||'—'}</span><span class:inactive={!person.is_active} class="badge">{person.is_active?'有効':'無効'}</span><span class="chevron">⌄</span></summary>
 <div class="editor"><form method="POST" action="?/save" use:enhance={submit}><input type="hidden" name="facilityId" value={data.facilityId}/><input type="hidden" name="id" value={person.id}/><input type="hidden" name="updated_at" value={person.updated_at}/>
 <fieldset disabled={!data.canEdit||busy}><div class="fields"><label>氏名<input name="name" value={person.name} required maxlength="100"/></label><label>ふりがな<input name="kana" value={person.kana??''} maxlength="100"/></label><label>表示名<input name="nickname" value={person.nickname??''} maxlength="100"/></label><label>部署<input name="department" value={person.department??''} maxlength="100"/></label></div>
 <div class="flags"><label><input type="checkbox" name="is_active" checked={person.is_active}/>有効</label><label><input type="checkbox" name="can_take_reservation" checked={person.can_take_reservation}/>PMSの予約・部屋案内候補</label><label><input type="checkbox" name="exclude_from_room_assignment" checked={person.exclude_from_room_assignment}/>PMSの部屋割りから除外</label></div></fieldset>
 <div class="form-actions"><span>{person.hr_employee_id.startsWith('book:')?'Bookで登録':'人事名簿から取込'}{Object.keys(person.book_overrides??{}).length?' · Bookで編集済み':''}</span>{#if data.canEdit}<button class="primary" disabled={busy}>変更を保存</button>{/if}</div></form>
 {#if data.canEdit&&person.is_active}<form method="POST" action="?/remove" use:enhance={submit} onsubmit={event=>{if(!confirm(person.name+'さんを削除（無効化）しますか？ 過去の対応履歴は残ります。'))event.preventDefault();}}><input type="hidden" name="facilityId" value={data.facilityId}/><input type="hidden" name="id" value={person.id}/><input type="hidden" name="updated_at" value={person.updated_at}/><button class="remove" disabled={busy}>削除（無効化）</button></form>{/if}
 </div></details>{:else}<p class="empty">該当するスタッフはいません。</p>{/each}</div>
</section>
<style>
.staff-page{max-width:1100px;margin:auto;color:#304438}header{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:1rem}header p{font-size:.75rem;color:#7e8b75}h1{font-size:1.8rem;font-weight:650}h2{font-size:1rem;font-weight:600;margin-bottom:1rem}.description{font-size:.8rem;color:#798571;line-height:1.9;margin-bottom:1.5rem;max-width:800px}button{border:1px solid #d7dfd1;border-radius:.55rem;padding:.65rem 1rem;font-size:.78rem;transition:background .15s,box-shadow .15s,transform .15s}button:hover:not(:disabled){box-shadow:0 3px 8px #243e2520;transform:translateY(-1px)}button:disabled{opacity:.5}.primary{background:#57734b;color:#fff;border-color:#57734b}.primary:hover{background:#405b36}.feedback{padding:.9rem 1rem;background:#edf5e7;border-radius:.6rem;font-size:.8rem;margin:1rem 0}.error{background:#fff0e9;color:#9b5235}.create-panel,.roster{background:#fff;border:1px solid #e1e7da;border-radius:.85rem;overflow:hidden}.create-panel{padding:1.3rem;margin-bottom:1rem}.toolbar{display:flex;align-items:center;gap:1rem;flex-wrap:wrap;margin:1.4rem 0 1rem;font-size:.75rem;color:#75816e}.toolbar>input{flex:1;min-width:220px;max-width:450px}.toolbar label{display:flex;align-items:center;gap:.45rem}.toolbar>span{margin-left:auto}input:not([type=checkbox]){width:100%;border:1px solid #dbe3d4;border-radius:.5rem;padding:.6rem .75rem;background:#fff;color:#304438;font-size:.8rem}input:focus-visible{outline:2px solid #7e9f6c;outline-offset:2px}details+details{border-top:1px solid #e8ede2}summary{display:flex;align-items:center;gap:1rem;padding:1.1rem 1.3rem;cursor:pointer;list-style:none;transition:background .15s}summary::-webkit-details-marker{display:none}summary:hover{background:#f2f6ec}.avatar{display:grid;place-items:center;width:38px;height:38px;background:#edf2e8;border-radius:50%;font-size:.85rem;color:#6e805e}.identity{display:grid;gap:.25rem;flex:1}.identity strong{font-size:.88rem;font-weight:550}.identity small,.department{font-size:.72rem;color:#8a9580}.department{width:24%}.badge{font-size:.68rem;padding:.25rem .6rem;border-radius:1rem;background:#eef4e7;color:#617c51}.inactive{background:#efefeb;color:#93968c}.chevron{color:#8c9b7f}.editor{border-top:1px solid #e9ede4;padding:1.2rem 1.4rem;background:#fcfdf9}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.fields label{display:grid;gap:.4rem;font-size:.72rem;color:#7c8973}.flags{display:flex;flex-wrap:wrap;gap:1rem;margin:1.2rem 0;font-size:.75rem;color:#78856f}.flags label{display:flex;gap:.4rem;align-items:center}.form-actions{display:flex;align-items:center;justify-content:space-between;gap:1rem;font-size:.67rem;color:#89947e}.remove{color:#a5674d;background:#fff;margin-top:.8rem}.remove:hover{background:#fff0e9}.empty{padding:2rem;text-align:center;font-size:.85rem;color:#8a9680}fieldset{border:0;padding:0;margin:0}@media(max-width:650px){.fields{grid-template-columns:1fr}.department{display:none}summary{padding:1rem;gap:.7rem}h1{font-size:1.4rem}.editor{padding:1rem}.toolbar>input{max-width:none}}
</style>
